// ===== Audit.gs =====
/**
 * Audit — Tally-style edit log. Every INSERT / ALTER / DELETE / LOCK / LOGIN / DENIED is recorded
 * with user, time, record, version and a compact before→after diff.
 */
var Audit = (function () {
  function log(user, action, table, recordId, changes, device, version) {
    try {
      Db.appendRows('AuditLog', [{
        id: Db.newId('A'), ts: nowIso_(), user_id: user ? user.id : '', user_name: user ? (user.name || user.username) : 'system',
        action: action, table: table, record_id: recordId || '', version: version || '',
        changes_json: changes ? JSON.stringify(changes).slice(0, 45000) : '', device: String(device || '').slice(0, 120)
      }]);
    } catch (e) { /* audit must never break the main write */ }
  }
  /** Compact diff of two records; skips internal and listed fields. */
  function diff(before, after, skip) {
    skip = (skip || []).concat(['_row', 'updated_at', 'updated_by', 'version']);
    var out = {};
    Object.keys(after || {}).forEach(function (k) {
      if (skip.indexOf(k) >= 0) return;
      var a = before ? before[k] : undefined, b = after[k];
      if (String(a === undefined ? '' : a) !== String(b === undefined ? '' : b)) out[k] = { from: a, to: b };
    });
    return out;
  }
  function history(ctx, p) {
    var rows = Db.all('AuditLog').filter(function (r) {
      if (p.table && r.table !== p.table) return false;
      if (p.record_id && String(r.record_id) !== String(p.record_id)) return false;
      if (p.user_id && r.user_id !== p.user_id) return false;
      if (p.from && r.ts < p.from) return false;
      if (p.to && r.ts > p.to + 'T23:59:59') return false;
      return true;
    });
    if (ctx.user.role !== 'super_admin' && !Auth.can(ctx.user, 'users')) rows = rows.filter(function (r) { return r.user_id === ctx.user.id; });
    rows.sort(function (a, b) { return a.ts < b.ts ? 1 : -1; });
    return rows.slice(0, num_(p.limit) || 200).map(function (r) {
      var ch = null; try { ch = r.changes_json ? JSON.parse(r.changes_json) : null; } catch (e) { ch = r.changes_json; }
      return { id: r.id, ts: r.ts, user: r.user_name, action: r.action, table: r.table, record_id: r.record_id, version: r.version, changes: ch };
    });
  }
  return { log: log, diff: diff, history: history };
})();

/**
 * Review — things the software is not confident about go here; a digest mail goes to the Super Admin
 * at night ONLY if there is something that needs review.
 */
var Review = (function () {
  function add(type, table, refId, message, suggestion) {
    Db.appendRows('ReviewQueue', [{ id: Db.newId('RV'), ts: nowIso_(), type: type, ref_table: table, ref_id: refId, message: message, suggestion: suggestion || '', status: 'open', resolved_by: '', resolved_at: '' }]);
  }
  function list(ctx) {
    Auth.require(ctx.user, 'console');
    return Db.all('ReviewQueue').filter(function (r) { return r.status === 'open'; }).sort(function (a, b) { return a.ts < b.ts ? 1 : -1; });
  }
  function resolve(ctx, p) {
    Auth.require(ctx.user, 'console');
    var r = Db.update('ReviewQueue', p.id, { status: p.status || 'done', resolved_by: ctx.user.id, resolved_at: nowIso_() });
    Audit.log(ctx.user, 'REVIEW', 'ReviewQueue', p.id, { status: r.status }, ctx.device);
    return r;
  }
  function sendDigestIfNeeded() {
    var open = Db.all('ReviewQueue').filter(function (r) { return r.status === 'open' && r.ts >= today_(); });
    if (!open.length) return;
    var admins = Db.all('Users').filter(function (u) { return u.role === 'super_admin' && u.email; });
    if (!admins.length) return;
    var shop = Db.setting('shop_name', 'Shop');
    var html = '<div style="font-family:Inter,Arial,sans-serif;max-width:640px"><h2 style="margin:0 0 6px">' + shop + ' — ' + open.length + ' cheezein review ke liye</h2>' +
      '<p style="color:#666;margin:0 0 16px">Aaj software ko in par confidence nahi tha. Console ▸ Review mein ek click mein OK/Edit karein.</p>' +
      '<table style="border-collapse:collapse;width:100%;font-size:14px">' +
      open.map(function (r) { return '<tr><td style="padding:8px;border-bottom:1px solid #eee"><b>' + esc_(r.type) + '</b><br>' + esc_(r.message) + (r.suggestion ? '<br><span style="color:#b98a00">Suggestion: ' + esc_(r.suggestion) + '</span>' : '') + '</td></tr>'; }).join('') +
      '</table></div>';
    admins.forEach(function (a) {
      try { MailApp.sendEmail({ to: a.email, subject: '[' + shop + '] ' + open.length + ' review items — ' + today_(), htmlBody: html }); } catch (e) { /* quota */ }
    });
  }
  return { add: add, list: list, resolve: resolve, sendDigestIfNeeded: sendDigestIfNeeded };
})();

