        if (!p.hsn && category !== 'Phone') Review.add('HSN check', 'Items', item.id, '"' + brand.name + ' ' + model + '" (' + category + ') par HSN ' + hsn + ' auto laga', 'Category ke hisaab se HSN confirm karein');
