      if (f.model && u.model !== f.model) return false;
      if (f.ram && String(u.ram).replace(/\D/g, '') !== String(f.ram).replace(/\D/g, '')) return false;
      if (f.storage && String(u.storage).replace(/\D/g, '') !== String(f.storage).replace(/\D/g, '')) return false;
      if (f.colour && String(u.colour).toLowerCase() !== String(f.colour).toLowerCase()) return false;
      if (f.condition && u.condition !== f.condition) return false;
      if (f.price_min && u.sale_price < num_(f.price_min)) return false;
      if (f.price_max && u.sale_price > num_(f.price_max)) return false;
