    if (p.imei1 !== undefined) { var i1 = String(p.imei1).replace(/\D/g, ''); if (i1 && i1.length !== 15) throw apiError_('IMEI 15 digit ka hota hai'); patch.imei1 = i1; if (u.notes === 'IMEI pending') patch.notes = ''; }
    if (p.imei2 !== undefined) patch.imei2 = String(p.imei2).replace(/\D/g, '');
