    if (p.landing_cost !== undefined) { Auth.require(ctx.user, 'edit_all'); patch.landing_cost = round2_(p.landing_cost); }
    var after = Db.update('StockUnits', u.id, patch);
    Audit.log(ctx.user, 'ALTER', 'StockUnits', u.id, Audit.diff(u, after), ctx.device);
    if (patch.status) Db.appendRows('StockMoves', [{ id: Db.newId('M'), date: today_(), variant_id: u.variant_id, unit_id: u.id, qty: patch.status === 'In Stock' ? 1 : -1, type: 'Adjust:' + patch.status, ref_type: 'Adjust', ref_id: p.reason || '', user_id: ctx.user.id }]);
