    ['Sales', 'Sales'], ['Sales – Second Hand (Margin)', 'Sales'], ['Service Income', 'Income'], ['Other Charges', 'Income'],
    ['Purchase', 'Purchase'], ['Purchase – Old Phones', 'Purchase'],
    ['Output CGST', 'Tax'], ['Output SGST', 'Tax'], ['Output IGST', 'Tax'], ['Input CGST', 'Tax'], ['Input SGST', 'Tax'], ['Input IGST', 'Tax'],
    ['Round Off', 'RoundOff'], ['Discount Allowed', 'Expense'],
    ['Rent', 'Expense'], ['Salary', 'Expense'], ['Electricity', 'Expense'], ['Tea & Refreshments', 'Expense'], ['Transport', 'Expense'], ['Marketing', 'Expense'], ['Shop Expenses', 'Expense'], ['Bank Charges', 'Expense'], ['Interest on Loan', 'Expense'], ['Repair Parts', 'DirectExpense'],
    ['Interest Received', 'Income']
