    Db.appendRows('JournalEntries', live.map(function (j) { return { id: Db.newId('J'), date: date || today_(), ref_type: refType + 'Rev', ref_id: refId, ref_no: j.ref_no, ledger_id: j.ledger_id, ledger_name: j.ledger_name, dr: j.cr, cr: j.dr, narration: note || 'Reversal', party_id: j.party_id, created_at: nowIso_(), created_by: ctx && ctx.user ? ctx.user.id : 'system', reversed: true }; }));
