      var pt = parties[a.party_id] = parties[a.party_id] || { party_id: a.party_id, total: 0, b0: 0, b8: 0, b31: 0, b61: 0, bills: 0, on_account: 0, oldest: null, byBill: {} };
      if (a.ref_type === 'New Ref') { var bb = pt.byBill[a.bill_id] = pt.byBill[a.bill_id] || { date: a.date, amt: 0 }; bb.amt += num_(a.amount); }
      else if (a.ref_type === 'Agst Ref') { var bb2 = pt.byBill[a.bill_id] = pt.byBill[a.bill_id] || { date: a.date, amt: 0 }; bb2.amt -= num_(a.amount); }
