    Journal.post(ctx, 'Purchase', pu.id, pu.pur_no, pu.bill_date, entries, (pu.type === 'OldPhone' ? 'Old phone bought from ' : 'Purchase from ') + pu.supplier_name + (pu.supplier_bill_no ? ' bill ' + pu.supplier_bill_no : ''), partyId);
