    var units = Db.where('StockUnits', function (u) { return u.purchase_id === pu.id && (p.unit_ids || []).indexOf(u.id) >= 0; });
    units.forEach(function (u) { if (u.status !== 'In Stock') throw apiError_('IMEI ' + u.imei1 + ' stock mein nahi (' + u.status + ')'); });
    var qtyLines = p.qty_lines || [];
    if (!units.length && !qtyLines.length) throw apiError_('Kya wapas kiya?');
    var date = p.date || today_(), dnId = Db.newId('PU'), dnNo = Db.nextNumber('DN');
