    units.forEach(function (u) { var bl = recLines[u.purchase_line_id] ? billLines[recLines[u.purchase_line_id].bill_line_id] : null; var r = bl ? num_(bl.gst_rate) : num_(u.bill_gst_rate); taxable += num_(u.landing_cost); tax += num_(u.landing_cost) * r / 100; lines.push({ id: Db.newId('PBL'), purchase_id: dnId, line_no: lines.length + 1, bill_item_name: u.bill_item_name, hsn: u.bill_hsn, qty: 1, rate: num_(u.landing_cost), taxable: num_(u.landing_cost), gst_rate: r, tax: round2_(num_(u.landing_cost) * r / 100), line_type: 'Return' }); });
    qtyLines.forEach(function (ql) { var rl = Db.where('PurchaseReceiptLines', function (x) { return x.purchase_id === pu.id && x.variant_id === ql.variant_id; })[0]; if (!rl) throw apiError_('Yeh item is purchase mein nahi tha'); var bl = billLines[rl.bill_line_id] || {}; var rate = num_(rl.rate), q = num_(ql.qty), r = num_(bl.gst_rate); taxable += rate * q; tax += rate * q * r / 100; lines.push({ id: Db.newId('PBL'), purchase_id: dnId, line_no: lines.length + 1, bill_item_name: bl.bill_item_name || rl.variant_name, hsn: bl.hsn || '', qty: q, rate: rate, taxable: round2_(rate * q), gst_rate: r, tax: round2_(rate * q * r / 100), line_type: 'Return' }); Stock.bumpQty_(ql.variant_id, -q, -rate * q); Db.appendRows('StockMoves', [{ id: Db.newId('M'), date: date, variant_id: ql.variant_id, unit_id: '', qty: -q, type: 'PurchaseReturn', ref_type: 'DebitNote', ref_id: dnId, user_id: ctx.user.id }]); });
    taxable = round2_(taxable); tax = round2_(tax); var total = round2_(taxable + tax);
