    Journal.post(ctx, 'DebitNote', dnId, dnNo, date, entries, 'Debit note ' + dnNo + ' against ' + pu.pur_no, pu.supplier_id);
    if (num_(pu.pending) > 0.5 && pu.supplier_id) { var adj = Math.min(num_(pu.pending), total); Db.appendRows('BillAllocations', [{ id: Db.newId('BA'), date: date, party_id: pu.supplier_id, side: 'Payable', payment_id: dnId, ref_type: 'Agst Ref', bill_type: 'Purchase', bill_id: pu.id, bill_no: pu.pur_no, amount: adj, created_at: nowIso_(), created_by: ctx.user.id }]); Outstanding.syncBills_([pu.id], pu.supplier_id); if (total - adj > 0.5) Db.appendRows('BillAllocations', [{ id: Db.newId('BA'), date: date, party_id: pu.supplier_id, side: 'Payable', payment_id: dnId, ref_type: 'On Account', bill_type: '', bill_id: '', bill_no: '', amount: round2_(total - adj), created_at: nowIso_(), created_by: ctx.user.id }]); }
    else if (pu.supplier_id) Db.appendRows('BillAllocations', [{ id: Db.newId('BA'), date: date, party_id: pu.supplier_id, side: 'Payable', payment_id: dnId, ref_type: 'On Account', bill_type: '', bill_id: '', bill_no: '', amount: total, created_at: nowIso_(), created_by: ctx.user.id }]);
    Summary.bump(date, { purchases: -total });
