    var units = Db.where('StockUnits', function (u) { return u.purchase_id === pu.id; });
    if (units.some(function (u) { return u.status === 'Sold'; })) throw apiError_('Is purchase ka koi phone bik chuka hai — cancel nahi ho sakta. Debit note banayein.');
    Db.updateMany('StockUnits', units.map(function (u) { return { id: u.id, patch: { status: 'Returned', out_date: today_() } }; }));
    Db.where('PurchaseReceiptLines', function (l) { return l.purchase_id === pu.id; }).forEach(function (l) { var v = Db.byId('Variants', l.variant_id), it = v ? Db.byId('Items', v.item_id) : null; if (it && it.item_type === 'Quantity') Stock.bumpQty_(l.variant_id, -num_(l.qty), -num_(l.amount)); });
    var pays = Db.where('Payments', function (x) { return x.ref_type === 'Purchase' && x.ref_id === pu.id && x.status !== 'Void'; });
    Db.updateMany('Payments', pays.map(function (x) { return { id: x.id, patch: { status: 'Void', notes: 'purchase cancelled' } }; }));
    Journal.reverse(ctx, 'Purchase', pu.id, today_(), 'Purchase cancelled'); Journal.reverse(ctx, 'PurPay', pu.id, today_(), 'Purchase cancelled');
    Outstanding.voidRefsOf(pu.id);
