      v += ledEntry(pl, sign * num_(pu.total), false, [isDN ? (pu.ref_id && Db.byId('Purchases', pu.ref_id) ? { type: 'Agst Ref', name: (Db.byId('Purchases', pu.ref_id).supplier_bill_no || Db.byId('Purchases', pu.ref_id).pur_no), amount: sign * num_(pu.total) } : { type: 'On Account', name: pu.pur_no, amount: sign * num_(pu.total) }) : { type: 'New Ref', name: pu.supplier_bill_no || pu.pur_no, amount: sign * num_(pu.total) }]);
