      if (num_(pu.sgst)) v += ledEntry(tn(Ledger.byName('Input SGST')), -sign * num_(pu.sgst), true);
      if (num_(pu.igst)) v += ledEntry(tn(Ledger.byName('Input IGST')), -sign * num_(pu.igst), true);
      bl.forEach(function (b) { var goods = !b.line_type || b.line_type === 'Return'; var led = (b.line_type === 'Discount' && !num_(b.gst_rate)) ? tn(Ledger.ensure('Discount Received', 'Income')) : purLed; if (withInv && goods) v += invEntry(b.bill_item_name, num_(b.qty), -sign * num_(b.taxable), purLed); else v += ledEntry(led, -sign * num_(b.taxable), true); });
      v += '</VOUCHER>\n';
