    if (allocs) allocs.forEach(function (a) { if (!a.amount) return; s += '<BILLALLOCATIONS.LIST>\n<NAME>' + x(a.name) + '</NAME>\n<BILLTYPE>' + a.type + '</BILLTYPE>\n<AMOUNT>' + amt(a.amount) + '</AMOUNT>\n</BILLALLOCATIONS.LIST>\n'; });
