function setupDatabase() {
  var ss = linkDatabase_();
  Object.keys(SCHEMA).forEach(function (name) {
    var sh = ss.getSheetByName(name);
    if (!sh) {
      sh = ss.insertSheet(name);
      sh.getRange(1, 1, 1, SCHEMA[name].length).setValues([SCHEMA[name]]);
      sh.setFrozenRows(1);
      sh.getRange(1, 1, 1, SCHEMA[name].length).setFontWeight('bold').setBackground('#111111').setFontColor('#F5B800');
    }
  });
  // migration: add any new columns to existing tabs (appended at the end, so old data stays aligned)
  Object.keys(SCHEMA).forEach(function (name) {
    var sh = ss.getSheetByName(name); if (!sh) return;
    var have = sh.getRange(1, 1, 1, Math.max(1, sh.getLastColumn())).getValues()[0].filter(function (x) { return x !== ''; });
    var missing = SCHEMA[name].filter(function (c) { return have.indexOf(c) < 0; });
    if (missing.length) sh.getRange(1, have.length + 1, 1, missing.length).setValues([missing]).setFontWeight('bold').setBackground('#111111').setFontColor('#F5B800');
  });
  var first = ss.getSheets()[0];
  if (first.getName() === 'Sheet1' && first.getLastRow() === 0) ss.deleteSheet(first);
  seedDefaults_();
  SpreadsheetApp.flush();
  Logger.log('Database ready. Now run createSuperAdmin() once, then deploy as Web App.');
}

/**
 * Finds or creates the DB spreadsheet and remembers its ID in Script Properties.
 * Works both when the script is bound to a Sheet and when it is a standalone script.
 */
function linkDatabase_() {
  var props = PropertiesService.getScriptProperties();
  var id = props.getProperty('DB_SPREADSHEET_ID'), ss = null;
  if (id) { try { ss = SpreadsheetApp.openById(id); } catch (e) { ss = null; } }
  if (!ss) { try { ss = SpreadsheetApp.getActiveSpreadsheet(); } catch (e) { ss = null; } }
  if (!ss) {
    ss = SpreadsheetApp.create('GS Telecom ERP – DB');
    Logger.log('Created new database spreadsheet: ' + ss.getUrl());
  }
  props.setProperty('DB_SPREADSHEET_ID', ss.getId());
  Db.setSpreadsheet(ss);
  Logger.log('Database spreadsheet linked: ' + ss.getUrl());
  return ss;
}

